mapper.insert:

 		SELECT NVL(MAX(reply_no),0) + 1
 		FROM album_comment

 	INSERT INTO album_comment
 			(
 				reply_no
	  			,album_no
	  			,content
	  			,parent_reply_no
	  			,user_name
	  			,reply_date
	  			,reply_state
 			)
 		VALUES
 			(
 				#{replyNo}
 				, #{albumNo}
 				, #{content}
 				, #{parentReplyNo}
 				, #{userName}
 				, sysdate
 				, 'B201'
 			)
